const origTitle = document.title;
let currentStation;
const stationView = {
  mount: (feature) => {
    // set title
    const { properties, geometry } = feature;
    const {
      name,
      'name_zh-Hans': name_zh_Hans,
      name_ta,
      station_codes,
      station_colors,
      wikipedia_slug,
    } = properties;

    document.title = `${name} / ${name_zh_Hans} / ${name_ta} (${station_codes}) – RailRouter SG`;

    $station.classList.remove('min');

    const zoom = map.getZoom();
    const isScreenLarge = window.innerWidth >= 640;
    const padding = isScreenLarge ? { left: 320 } : { bottom: window.innerHeight / 2 };
    if (zoom <= 13) {
      map.jumpTo({
        center: geometry.coordinates,
        zoom: 16.5,
        pitch: 60,
        padding,
      });
    } else {
      map.easeTo({
        center: geometry.coordinates,
        zoom: 16.5,
        pitch: 60,
        padding,
        duration: 500,
      });
    }

    if (station_codes === currentStation) return;

    currentStation = station_codes;
    $station.innerHTML = `
      <header>
        <span class="pill">
          ${station_codes
        .split('-')
        .map(
          (c, i) =>
            `<span class="${station_colors.split('-')[i]}">${c.replace(
              /^([a-z]+)/i,
              '$1 ',
            )}</span>`,
        )
        .join('')}
        </span>
        <h2>
          ${name}<br>
          <span lang="zh" class="ib">${name_zh_Hans}</span>&nbsp;&nbsp;&nbsp;
          <span lang="ta" class="ib">${name_ta}</span>
        </h2>
      </header>
      <div class="scrollable">
        <div class="exits"></div>
        <div class="arrivals"></div>
        <div class="wikipedia"></div>
        <div class="external-links"></div>
      </div>
      `;
    $station.classList.add('open');
    stationsExits.mount(exitsData[station_codes], feature);
    stationArrivals.mount(station_codes, stationNames);
    wikipedia.mount(wikipedia_slug);
    externalLinks.mount(station_codes);
  },
  unmount: () => {
    document.title = origTitle;
    currentStation = null;
    $station.classList.remove('open');
    $station.classList.remove('min');
    stationArrivals.unmount();

    const zoom = map.getZoom();
    const isScreenLarge = window.innerWidth >= 800;
    map.easeTo({
      zoom: zoom - 1,
      pitch: 0,
      bearing: 0,
      padding: isScreenLarge ? { left: 0 } : { bottom: 0 },
      duration: 500,
    });
  },
};

